/**
 * @name Arbitrary file write
 * @description Writing to user-controlled file paths without validation
 * @kind path-problem
 * @problem.severity high
 * @id py/click-arbitrary-file-write
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ArbitraryFileWriteConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode p |
      p.getParameter().getName() in ["filename", "path", "file", "dest", "destination"] and
      source = p
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("open").getACall() and
        call.getArg(1).asExpr().(StringLiteral).getText().matches("%w%") and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("pathlib").getMember("Path").getReturn().getMember("write_text").getACall() and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("pathlib").getMember("Path").getReturn().getMember("write_bytes").getACall() and
        sink = call.getArg(0)
      )
    )
  }
}

module ArbitraryFileWriteFlow = TaintTracking::Global<ArbitraryFileWriteConfig>;
import ArbitraryFileWriteFlow::PathGraph

from ArbitraryFileWriteFlow::PathNode source, ArbitraryFileWriteFlow::PathNode sink
where ArbitraryFileWriteFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Arbitrary file write from $@.", source.getNode(), "user input"

